import React from 'react';

import {
  mapFrontProductToBackAdd,
  mapFrontProductToBackUpdate,
} from '@apps/Products/@mappers/products.mapper';
import { addProduct, updateProduct } from '@apps/Products/@services/products.service';
import { IProductFull } from '@apps/Products/@types/products.types';
import HelpInfo from '@components/HelpInfo';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

interface IProductAddModalProps {
  data?: Partial<IProductFull>;
  onSave: (saved: IProductFull) => void;
}

const ProductAddModal: React.FC<IProductAddModalProps> = ({ data, onSave }) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState<Error>();
  const [addData, setAddData] = React.useState<IProductFull>({
    id: 0,
    name: '',
    protein: -1,
    fat: -1,
    carbs: -1,
    energy: -1,
    search_regex: '',
    ...(data ?? {}),
  });

  const handleInputChange =
    <K extends keyof IProductFull>(field: keyof IProductFull) =>
    (value: IProductFull[K]) => {
      setAddData((fd) => ({
        ...(fd as IProductFull),
        [field]: value,
      }));
    };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>): Promise<void> => {
    e.preventDefault();
    try {
      setIsLoading(true);

      if (!addData.id) {
        const id = await addProduct(mapFrontProductToBackAdd(addData));

        onSave({
          ...addData,
          id,
        });
      } else {
        await updateProduct(mapFrontProductToBackUpdate(addData));

        onSave(addData);
      }
    } catch (er) {
      setError(er as Error);
    } finally {
      setIsLoading(false);
    }
  };
  return (
    <form style={{ minWidth: 420 }} onSubmit={handleSubmit} className="vertical-gapped">
      <PohInput
        required
        label="Название"
        value={addData.name}
        onChange={handleInputChange('name')}
        placeholder="Название продукта"
        disabled={isLoading}
      />
      <PohRow>
        <PohCol sm={3} xs={3}>
          <PohInput
            required
            label="Ккал"
            value={addData.energy < 0 ? '' : addData.energy.toString()}
            onChange={(v) => handleInputChange('energy')(v ? +v : -1)}
            type={InputTypes.number}
            min="0"
            max="1000"
            step={0.01}
            placeholder="На 100 грамм"
            disabled={isLoading}
          />
        </PohCol>
        <PohCol sm={3} xs={3}>
          <PohInput
            required
            label="Белки"
            value={addData.protein < 0 ? '' : addData.protein.toString()}
            onChange={(v) => handleInputChange('protein')(v ? +v : -1)}
            type={InputTypes.number}
            min="0"
            max="100"
            step={0.01}
            placeholder="На 100 грамм"
            disabled={isLoading}
          />
        </PohCol>
        <PohCol sm={3} xs={3}>
          <PohInput
            required
            label="Жиры"
            value={addData.fat < 0 ? '' : addData.fat.toString()}
            onChange={(v) => handleInputChange<'fat'>('fat')(v ? +v : -1)}
            type={InputTypes.number}
            min="0"
            max="100"
            step={0.01}
            placeholder="На 100 грамм"
            disabled={isLoading}
          />
        </PohCol>
        <PohCol sm={3} xs={3}>
          <PohInput
            required
            label="Углеводы"
            value={addData.carbs < 0 ? '' : addData.carbs.toString()}
            onChange={(v) => handleInputChange('carbs')(v ? +v : -1)}
            type={InputTypes.number}
            min="0"
            max="100"
            step={0.01}
            placeholder="На 100 грамм"
            disabled={isLoading}
          />
        </PohCol>
      </PohRow>

      <PohRow>
        <PohCol sm={12}>
          <PohInput
            label={
              <div>
                <HelpInfo className="float-end">
                  <p>
                    По этому регулярному выражению будет производиться поиск при автоматическом
                    добавлении позиций из чека.
                  </p>
                  <p>
                    Например: чтобы найти продукт <strong>Макароны</strong> по позиции в чеке{' '}
                    <strong>Макаронные изделия</strong> можно использовать регулярное выражение{' '}
                    <code>макарон</code>
                  </p>
                  <p>
                    Обрамляющие слеши и модификаторы <code>/.../ig</code> указывать не нужно, они
                    будут применены автоматически
                  </p>
                </HelpInfo>
                RegExp для поиска
              </div>
            }
            labelClassName="w-100"
            value={addData.search_regex}
            onChange={handleInputChange('search_regex')}
            placeholder="^Макарон"
            disabled={isLoading}
          />
        </PohCol>
      </PohRow>
      <footer className="text-end pt-3">
        {error && <PohAlert variant={AlertVariant.Danger}>{error.message}</PohAlert>}
        <PohButton type="submit">Сохранить</PohButton>
      </footer>
    </form>
  );
};

export default ProductAddModal;
