import React from 'react';

import InfoCircle from '@pohodnik/icons/svg/Signs/InfoCircle';
import clsx from 'clsx';

import { uniqueId } from '@helpers/unuqueId';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';

import styles from './styles.module.less';

interface IHelpInfoProps extends React.HTMLAttributes<HTMLSpanElement> {
  children: React.ReactNode;
}

const HelpInfo: React.FC<IHelpInfoProps> = ({ children, ...rest }) => {
  const idRef = React.useRef(uniqueId('help'));
  return (
    <span {...rest} className={clsx(rest.className, styles.container)}>
      <button
        type="button"
        popoverTarget={idRef.current}
        popoverTargetAction="toggle"
        className={clsx('text-info', styles.activator)}
      >
        <InfoCircle />
      </button>
      <div
        id={idRef.current}
        className={clsx(styles.popover, 'border border-info p-2')}
        popover="auto"
      >
        <PohButton
          icon={IconsEnum.close}
          className="float-end"
          popoverTarget={idRef.current}
          popoverTargetAction="hide"
          size={ButtonSize.Small}
          variant={ButtonVariant.Light}
        />
        {children}
      </div>
    </span>
  );
};

export default HelpInfo;
